import React from "react";
const Htmlquiz = () => {
    return (
        <>
            <div style={{
                maxWidth: "700px",
                margin: "40px auto",
                padding: "30px",
                borderRadius: "20px",
                background: "#ffffff",
                boxShadow: "0 10px 30px rgba(0,0,0,0.15)",
                fontFamily: "Arial"
            }}>

                <h1 style={{
                    textAlign: "center",
                    color: "#5b8def"
                }}>
                    HTML Quiz
                </h1>

                {(() => {

                    const questions = [
                        {
                            question: "HTML ka full form kya hai?",
                            options: [
                                "Hyper Text Markup Language",
                                "High Text Markup Language",
                                "Hyper Tool Multi Language",
                                "Home Text Markup Language"
                            ],
                            answer: "Hyper Text Markup Language"
                        },
                        {
                            question: "HTML mein sabse bada heading tag kaunsa hai?",
                            options: [
                                "<h1>",
                                "<h6>",
                                "<head>",
                                "<heading>"
                            ],
                            answer: "<h1>"
                        },
                        {
                            question: "Paragraph banane ke liye kaunsa tag use hota hai?",
                            options: [
                                "<p>",
                                "<para>",
                                "<text>",
                                "<paragraph>"
                            ],
                            answer: "<p>"
                        },
                        {
                            question: "Image lagane ke liye kaunsa tag use hota hai?",
                            options: [
                                "<image>",
                                "<img>",
                                "<picture>",
                                "<src>"
                            ],
                            answer: "<img>"
                        },
                        {
                            question: "Link banane ke liye kaunsa tag use hota hai?",
                            options: [
                                "<link>",
                                "<a>",
                                "<href>",
                                "<url>"
                            ],
                            answer: "<a>"
                        }
                    ];

                    const [current, setCurrent] = React.useState(0);
                    const [selected, setSelected] = React.useState("");
                    const [score, setScore] = React.useState(0);
                    const [finished, setFinished] = React.useState(false);

                    const selectAnswer = (option) => {

                        if (selected !== "") return;

                        setSelected(option);

                        if (option === questions[current].answer) {
                            setScore(score + 1);
                        }
                    };

                    const nextQuestion = () => {

                        if (selected === "") {
                            alert("Pehle answer select karo!");
                            return;
                        }

                        if (current < questions.length - 1) {

                            setCurrent(current + 1);
                            setSelected("");

                        } else {

                            setFinished(true);

                        }
                    };

                    const restartQuiz = () => {

                        setCurrent(0);
                        setSelected("");
                        setScore(0);
                        setFinished(false);

                    };

                    if (finished) {

                        return (
                            <div style={{
                                textAlign: "center",
                                marginTop: "30px"
                            }}>

                                <h2>🎉 Quiz Completed!</h2>

                                <h1>
                                    Your Score: {score} / {questions.length}
                                </h1>

                                <p style={{
                                    fontSize: "18px"
                                }}>
                                    Keep Learning HTML 🚀
                                </p>

                                <button
                                    onClick={restartQuiz}
                                    style={{
                                        padding: "12px 25px",
                                        background: "#5b8def",
                                        color: "white",
                                        border: "none",
                                        borderRadius: "10px",
                                        cursor: "pointer",
                                        fontSize: "16px"
                                    }}
                                >
                                    Restart Quiz
                                </button>

                            </div>
                        );
                    }

                    return (
                        <div>

                            <p style={{
                                textAlign: "right",
                                color: "#777",
                                fontWeight: "bold"
                            }}>
                                Question {current + 1} / {questions.length}
                            </p>

                            <h2 style={{
                                marginBottom: "25px"
                            }}>
                                {questions[current].question}
                            </h2>

                            <div>

                                {questions[current].options.map((option, index) => {

                                    let background = "#f5f5f5";
                                    let border = "2px solid #ddd";

                                    if (selected !== "") {

                                        if (option === questions[current].answer) {
                                            background = "#d4edda";
                                            border = "2px solid green";
                                        }

                                        else if (option === selected) {
                                            background = "#f8d7da";
                                            border = "2px solid red";
                                        }
                                    }

                                    return (
                                        <button
                                            key={index}
                                            onClick={() => selectAnswer(option)}
                                            style={{
                                                display: "block",
                                                width: "100%",
                                                padding: "15px",
                                                marginBottom: "12px",
                                                border: border,
                                                borderRadius: "10px",
                                                background: background,
                                                textAlign: "left",
                                                fontSize: "16px",
                                                cursor: "pointer"
                                            }}
                                        >
                                            {option}
                                        </button>
                                    );

                                })}

                            </div>

                            <button
                                onClick={nextQuestion}
                                style={{
                                    width: "100%",
                                    padding: "15px",
                                    marginTop: "10px",
                                    background: "#5b8def",
                                    color: "white",
                                    border: "none",
                                    borderRadius: "10px",
                                    fontSize: "17px",
                                    fontWeight: "bold",
                                    cursor: "pointer"
                                }}
                            >
                                {current === questions.length - 1
                                    ? "Finish Quiz"
                                    : "Next Question →"}
                            </button>

                        </div>
                    );

                })()}

            </div>
        </>
    )
}
